import { Component } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-dotnet-integration',
  template: `
    <button (click)="loadData()">Load policies</button>
    <div *ngIf="policies">{{ policies | json }}</div>
  `
})
export class DotnetIntegrationComponent {
  policies: any;

  constructor(private http: HttpClient) {}

  loadData() {
    this.http.get('/api/policies').subscribe({
      next: (result) => (this.policies = result),
      error: (error) => console.error('API error', error),
    });
  }
}

import { Injectable } from '@angular/core';
import { CanActivate, Router } from '@angular/router';

@Injectable({
  providedIn: 'root',
})
export class AuthGuard implements CanActivate {
  constructor(private router: Router) {}

  canActivate(): boolean {
    const authenticated = false;
    if (!authenticated) {
      this.router.navigate(['/login']);
    }
    return authenticated;
  }
}

