import { Component, OnInit, OnDestroy } from '@angular/core';

@Component({
  selector: 'app-lifecycle-hooks',
  template: `
    <div>
      <h2>Lifecycle Example</h2>
      <p>{{ message }}</p>
    </div>
  `
})
export class LifecycleHooksComponent implements OnInit, OnDestroy {
  message = '';
  timerId: any;

  ngOnInit() {
    this.message = 'Initialized';
    this.timerId = setInterval(() => {
      this.message = `Tick: ${new Date().toLocaleTimeString()}`;
    }, 1000);
  }

  ngOnDestroy() {
    clearInterval(this.timerId);
  }
}

import { Component } from '@angular/core';

@Component({
  selector: 'app-manage-list',
  template: `
    <div>
      <label>New item:
        <input type="text" [(ngModel)]="newItem" />
      </label>
      <button (click)="addItem()">Add</button>
      <ul>
        <li *ngFor="let item of items; let i = index">
          {{ item }} <button (click)="removeItem(i)">Remove</button>
        </li>
      </ul>
    </div>
  `
})
export class ManageListComponent {
  items: string[] = [];
  newItem = '';

  addItem() {
    if (this.newItem.trim()) {
      this.items.push(this.newItem.trim());
      this.newItem = '';
    }
  }

  removeItem(index: number) {
    this.items.splice(index, 1);
  }
}

